// Guard the AI output (R11): the UI and the database NEVER receive a broken score/tier.
// If the AI failed/continued or returned malformed data, fall back to tier 'review' with score null.
const lead = $('Normalize Lead Fields').first().json;
const out = $input.first().json?.output;
const valid =
  out &&
  typeof out.reasoning === 'string' && out.reasoning.trim().length > 0 &&
  typeof out.score === 'number' && Number.isFinite(out.score) &&
  out.score >= 0 && out.score <= 100 &&
  ['hot', 'warm', 'cold'].includes(out.tier) &&
  typeof out.resumo === 'string' && out.resumo.trim().length > 0;
const q = valid
  ? { reasoning: out.reasoning, score: out.score, tier: out.tier, resumo: out.resumo }
  : { reasoning: '[REVIEW] AI unavailable or invalid output', score: null, tier: 'review', resumo: '[REVIEW] check manually' };
return [{ json: { ...lead, ...q } }];

