// Merge all pending warm/cold leads into a single message (table), subdivided by tier.
// If there are no pending leads, return empty so Telegram does NOT fire.
const rows = $input.all().map(i => i.json);
if (rows.length === 0) return [];
const fmt = (r) => `#${r.id} • <b>${r.nome}</b> • ${r.contato}\n   ${r.tipo||'-'} | ${r.quantidade||'-'} | ${r.tema||'-'} | ${r.data_evento||'-'} | ${r.retirada||'-'}${r.tem_imagem?' | 📎':''}\n   ⭐ ${r.score}/100`;
const warm = rows.filter(r => r.tier === 'warm');
const cold = rows.filter(r => r.tier === 'cold');
let text = `📋 <b>Digest de leads — morno/frio</b>\n${rows.length} lead(s) acumulado(s)`;
if (warm.length) text += `\n\n🟡 <b>MORNO (${warm.length})</b>\n` + warm.map(fmt).join('\n');
if (cold.length) text += `\n\n🔵 <b>FRIO (${cold.length})</b>\n` + cold.map(fmt).join('\n');
const ids = rows.map(r => r.id);
return [{ json: { text, ids } }];
